// ═══════════════════════════════════════════════════════════════════
//  MUSIC HOOK
// ═══════════════════════════════════════════════════════════════════
const useAmbientMusic = () => {
  const [isOn, setIsOn] = useState(false);
  const synthRef = useRef(null);
  const loopRef = useRef(null);

  const toggle = useCallback(async () => {
    if (!isOn) {
      try {
        await Tone.start();
        if (!synthRef.current) {
          const reverb = new Tone.Reverb({ decay: 5, wet: 0.55 }).toDestination();
          const filter = new Tone.Filter(2200, 'lowpass').connect(reverb);
          const synth = new Tone.PolySynth(Tone.Synth, {
            oscillator: { type: 'triangle' },
            envelope: { attack: 1.0, decay: 0.4, sustain: 0.4, release: 2.5 }
          }).connect(filter);
          synth.volume.value = -20;
          synthRef.current = synth;

          const chords = [
            ['C4', 'E4', 'G4', 'B4'],
            ['F4', 'A4', 'C5', 'E5'],
            ['A3', 'C4', 'E4', 'G4'],
            ['G3', 'B3', 'D4', 'F4'],
          ];
          let i = 0;
          loopRef.current = new Tone.Loop((time) => {
            synth.triggerAttackRelease(chords[i % chords.length], '1n', time);
            const mel = ['E5', 'G5', 'A5', 'D5'][i % 4];
            synth.triggerAttackRelease(mel, '2n', time + 1, 0.35);
            i++;
          }, '1n');
          Tone.Transport.bpm.value = 58;
        }
        loopRef.current.start(0);
        Tone.Transport.start();
        setIsOn(true);
      } catch (e) { console.warn('music err', e); }
    } else {
      if (loopRef.current) loopRef.current.stop();
      Tone.Transport.pause();
      setIsOn(false);
    }
  }, [isOn]);

  useEffect(() => () => {
    if (loopRef.current) loopRef.current.dispose();
    if (synthRef.current) synthRef.current.dispose();
  }, []);

  return [isOn, toggle];
};

const playPluck = async () => {
  try {
    await Tone.start();
    const synth = new Tone.PluckSynth({ attackNoise: 0.8, dampening: 4500, resonance: 0.75 }).toDestination();
    synth.volume.value = -8;
    const notes = ['C5', 'E5', 'G5', 'A5', 'B5', 'D6'];
    synth.triggerAttack(notes[Math.floor(Math.random() * notes.length)]);
    setTimeout(() => synth.dispose(), 1800);
  } catch (e) {}
};

